style:
.tw-mochuan.resume-paper {
  color: #24383b;
}

.tw-mochuan.resume-paper .paper-header {
  position: relative;
  margin: 0 calc(var(--paper-mr, 15mm) * -1) 0 calc(var(--paper-ml, 15mm) * -1);
  padding: 9mm var(--paper-mr, 15mm) 8mm var(--paper-ml, 15mm);
  border: none;
  background: linear-gradient(118deg, #1f5f66 0%, #2b747b 54%, #194c53 100%);
  color: #fff;
  print-color-adjust: exact;
}

.tw-mochuan.resume-paper .paper-header--photo {
  align-items: center;
  gap: 7mm;
}

.tw-mochuan.resume-paper .paper-photo {
  width: 26mm;
  height: 32mm;
  border: 0.7mm solid rgba(255, 255, 255, 0.82);
  border-radius: 1.4mm;
  box-shadow: none;
  print-color-adjust: exact;
}

.tw-mochuan.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  background: rgba(255, 255, 255, 0.14);
  color: #fff;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 1.7);
  font-weight: 600;
}

.tw-mochuan.resume-paper .paper-name {
  color: #fff;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.05);
  letter-spacing: 0.14em;
}

.tw-mochuan.resume-paper .paper-identity {
  padding: 0;
  border: none;
  color: rgba(255, 255, 255, 0.68);
}

.tw-mochuan.resume-paper .paper-role {
  margin-top: 1.2mm;
  color: #fff;
  font-weight: 600;
}

.tw-mochuan.resume-paper .paper-role::before {
  content: "求职意向：";
  color: rgba(255, 255, 255, 0.64);
  font-weight: 400;
  font-size: calc(var(--paper-base-size) * 0.92);
}

.tw-mochuan.resume-paper .paper-contacts--labeled {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.2mm 7mm;
  margin-top: 4mm;
  padding-top: 3mm;
  border-top: 1px solid rgba(255, 255, 255, 0.22);
  color: #fff;
  font-size: calc(var(--paper-base-size) * 0.86);
}

.tw-mochuan.resume-paper .paper-contact + .paper-contact::before {
  display: none;
}

.tw-mochuan.resume-paper .paper-contact__label {
  color: rgba(255, 255, 255, 0.58);
}

.tw-mochuan.resume-paper .sidebar-layout {
  grid-template-columns: calc(var(--paper-ml, 15mm) + 60mm) minmax(0, 1fr);
  gap: 8mm;
  margin-left: calc(var(--paper-ml, 15mm) * -1);
  background: linear-gradient(
    90deg,
    #1f5f66 0 calc(var(--paper-ml, 15mm) + 60mm),
    transparent calc(var(--paper-ml, 15mm) + 60mm)
  );
  print-color-adjust: exact;
}

.tw-mochuan.resume-paper .sidebar-aside {
  grid-column: 1;
  grid-row: 1;
  padding: 6mm 5mm 6mm calc(var(--paper-ml, 15mm) + 5mm);
  background: #1f5f66;
  border-top: none;
  border-radius: 0;
  color: #fff;
  print-color-adjust: exact;
}

.tw-mochuan.resume-paper .sidebar-main {
  grid-column: 2;
  grid-row: 1;
  padding-top: 6mm;
}

.tw-mochuan.resume-paper .sidebar-aside .paper-section {
  margin-top: 5mm;
}

.tw-mochuan.resume-paper .sidebar-aside .paper-section__title {
  display: flex;
  align-items: center;
  gap: 2mm;
  color: #fff;
  font-size: calc(var(--paper-base-size) * 1);
  letter-spacing: 0.12em;
}

.tw-mochuan.resume-paper .sidebar-aside .paper-section__icon {
  display: grid;
  place-items: center;
  width: 5mm;
  height: 5mm;
  border: 0.35mm solid rgba(255, 255, 255, 0.55);
  border-radius: 50%;
  background: transparent;
  color: #fff;
}

.tw-mochuan.resume-paper .sidebar-aside .paper-section__icon svg {
  width: 56%;
  height: 56%;
}

.tw-mochuan.resume-paper .sidebar-aside .paper-section__title::after {
  border-top-color: rgba(255, 255, 255, 0.32);
}

.tw-mochuan.resume-paper .sidebar-aside .paper-section__body {
  color: rgba(255, 255, 255, 0.84);
  font-size: calc(var(--paper-base-size) * 0.92);
}

.tw-mochuan.resume-paper .sidebar-aside .paper-item-head {
  display: block;
}

.tw-mochuan.resume-paper .sidebar-aside .paper-item-period {
  margin-top: 0.5mm;
  color: rgba(255, 255, 255, 0.62);
}

.tw-mochuan.resume-paper .sidebar-aside .paper-item-title {
  color: #fff;
}

.tw-mochuan.resume-paper .sidebar-aside .paper-item-sub,
.tw-mochuan.resume-paper .sidebar-aside .paper-note,
.tw-mochuan.resume-paper .sidebar-aside .paper-plain,
.tw-mochuan.resume-paper .sidebar-aside .paper-rich {
  color: rgba(255, 255, 255, 0.78);
}

.tw-mochuan.resume-paper .sidebar-aside .paper-item-sub span + span::before {
  color: rgba(255, 255, 255, 0.4);
}

.tw-mochuan.resume-paper .sidebar-aside .paper-note__tag {
  color: #b9dfe2;
}

.tw-mochuan.resume-paper .sidebar-aside .paper-skills {
  grid-template-columns: minmax(0, 1fr);
  gap: 0.6mm;
}

.tw-mochuan.resume-paper .sidebar-aside .paper-skill {
  padding: 1mm 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.16);
}

.tw-mochuan.resume-paper .sidebar-aside .paper-skill__name {
  color: #fff;
  font-weight: 500;
  font-size: calc(var(--paper-base-size) * 0.92);
}

.tw-mochuan.resume-paper .sidebar-aside .paper-skill__dots {
  display: none;
}

.tw-mochuan.resume-paper .sidebar-aside .paper-skill__level {
  display: inline;
  color: rgba(255, 255, 255, 0.68);
  font-size: calc(var(--paper-base-size) * 0.82);
}

.tw-mochuan.resume-paper .paper-section .paper-section__title {
  color: #1c3d42;
}

.tw-mochuan.resume-paper .paper-section .paper-section__icon {
  display: grid;
  place-items: center;
  border: 0.4mm solid #2b747b;
  border-radius: 50%;
  background: #eef6f6;
  color: #226d75;
}

.tw-mochuan.resume-paper .paper-section .paper-section__title::after {
  border-top-color: color-mix(in srgb, #2b747b 42%, #fff);
}

.tw-mochuan.resume-paper .paper-section .paper-section__body {
  color: #2c3f42;
}

.tw-mochuan.resume-paper .paper-section .paper-item-title {
  color: #163237;
}

.tw-mochuan.resume-paper .paper-section .paper-item-period {
  color: #5f7f82;
}

.tw-mochuan.resume-paper .paper-section .paper-item-sub {
  color: #40595b;
}

.tw-mochuan.resume-paper .paper-section .paper-note__tag {
  color: #226d75;
}

.tw-mochuan.resume-paper .paper-footer {
  border-top: 1px solid #d7e4e4;
  color: #6c8486;
}

/* 显式选择的列表样式接管模板默认圆点装饰，避免 data-list 被模板 ul/li 规则盖掉。 */
.tw-mochuan.resume-paper .paper-rich ul[data-list],
.tw-mochuan.resume-paper .paper-rich ol[data-list] {
  margin: 0.5mm 0 0;
  padding-left: 1.2em;
}
.tw-mochuan.resume-paper .paper-rich ul[data-list] > li,
.tw-mochuan.resume-paper .paper-rich ol[data-list] > li {
  padding-left: 0;
  position: relative;
}
.tw-mochuan.resume-paper .paper-rich ul[data-list] > li::before,
.tw-mochuan.resume-paper .paper-rich ol[data-list] > li::before {
  content: none;
  width: auto;
  height: auto;
  border-radius: 0;
  background: none;
  border: 0;
  box-shadow: none;
  left: auto;
  right: auto;
  top: auto;
  margin: 0;
  padding: 0;
}
.tw-mochuan.resume-paper .paper-rich ul[data-list="disc"] { list-style-type: disc; }
.tw-mochuan.resume-paper .paper-rich ul[data-list="circle"] { list-style-type: circle; }
.tw-mochuan.resume-paper .paper-rich ul[data-list="square"] { list-style-type: square; }
.tw-mochuan.resume-paper .paper-rich ul[data-list="square-open"] { list-style-type: "□   "; }
.tw-mochuan.resume-paper .paper-rich ul[data-list="square-open"] > li::marker { font-size: 0.62em; }
.tw-mochuan.resume-paper .paper-rich ul[data-list="diamond"] { list-style-type: "◆   "; }
.tw-mochuan.resume-paper .paper-rich ul[data-list="diamond-open"] { list-style-type: "◇   "; }
.tw-mochuan.resume-paper .paper-rich ul[data-list="diamond"] > li::marker,
.tw-mochuan.resume-paper .paper-rich ul[data-list="diamond-open"] > li::marker { font-size: 0.62em; }
.tw-mochuan.resume-paper .paper-rich ul[data-list="triangle"] { list-style-type: "▸   "; }
.tw-mochuan.resume-paper .paper-rich ul[data-list="check"] { list-style-type: "✓   "; }
.tw-mochuan.resume-paper .paper-rich ul[data-list="check"] > li::marker { font-size: 0.75em; }
.tw-mochuan.resume-paper .paper-rich ol[data-list="decimal"] { list-style-type: decimal; }
.tw-mochuan.resume-paper .paper-rich ol[data-list="cjk"] { list-style-type: miniwho-cjk; }
.tw-mochuan.resume-paper .paper-rich ol[data-list="roman-upper"] { list-style-type: upper-roman; }
.tw-mochuan.resume-paper .paper-rich ol[data-list="roman-lower"] { list-style-type: lower-roman; }
.tw-mochuan.resume-paper .paper-rich ol[data-list="alpha-upper"] { list-style-type: upper-alpha; }
.tw-mochuan.resume-paper .paper-rich ol[data-list="alpha-lower"] { list-style-type: lower-alpha; }
.tw-mochuan.resume-paper .paper-rich ol[data-list="paren"] { padding-left: 1.2em; list-style: none; counter-reset: paren-item; }
.tw-mochuan.resume-paper .paper-rich ol[data-list="paren"] > li { position: relative; counter-increment: paren-item; }
.tw-mochuan.resume-paper .paper-rich ol[data-list="paren"] > li::before {
  content: "（" counter(paren-item) "）";
  position: absolute;
  right: calc(100% + 0.08em);
  top: 0;
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  font-size: 0.62em;
  line-height: 1.7;
  white-space: nowrap;
}
.tw-mochuan.resume-paper .paper-rich ol[data-list="paren-right"] { padding-left: 1.2em; list-style: none; counter-reset: paren-right-item; }
.tw-mochuan.resume-paper .paper-rich ol[data-list="paren-right"] > li { position: relative; counter-increment: paren-right-item; }
.tw-mochuan.resume-paper .paper-rich ol[data-list="paren-right"] > li::before {
  content: counter(paren-right-item) ")";
  position: absolute;
  right: calc(100% + 0.12em);
  top: 0;
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
